typedef float rational_t;
typedef float time_value_t;

class ai_interface;
class path_graph;
class region_node;
class chunk_file;
class stringx;
class pstring;

struct vector3d
{
  float x, y, z;
  vector3d& operator=(const vector3d&);
};

extern const vector3d ZEROVEC;

class path
{
  char data[92];
public:
  path();
  void clear();
};

class ai_path { char data[8]; };

enum eLocomotionType
{
  LOCOMOTION_NONE,
  LOCOMOTION_DIRECT,
  LOCOMOTION_WALK,
  LOCOMOTION_WINGED,
  LOCOMOTION_HELI
};

class ai_locomotion
{
public:
  typedef enum
  {
    _FORWARD, _FORWARD_R, _RIGHT, _BACKWARD_R, _BACKWARD,
    _BACKWARD_L, _LEFT, _FORWARD_L, _WINGED_IDLE, _JOCKEY_ANIMS
  } eJockeyAnim;
protected:
  ai_interface *owner;
  path current_path;
  ai_path my_path;
  path_graph *current_path_graph;
  int patrol_id;
  bool xz_movement;
  virtual ai_locomotion *make_copy(ai_interface *own);
  void copy(ai_locomotion *b);
  rational_t patrol_radius;
  time_value_t has_been_stuck_for_how_long;
  vector3d previous_pos;
  vector3d local_dest;
  vector3d start_pos;
  vector3d last_pos;
  vector3d target_pos;
  rational_t tgtrange;
  bool running_speed;
  bool use_path;
  int path_tries;
  bool wait_until_reached;
  bool wait_for_facing;
  virtual bool set_path(const vector3d&, rational_t, bool);
  virtual void set_goto_path(rational_t, bool);
  bool in_service;
  virtual void going_into_service();
  virtual void going_out_of_service();
  void read_data(chunk_file&);
  virtual void handle_chunk(chunk_file&, stringx&);
  eLocomotionType type;
  bool facing;
  bool playing_face_anim;
  vector3d face_dir;
  rational_t turn_speed;
  rational_t jockey_timer;
  rational_t jockey_stuck_timer;
  vector3d last_jockey_pos;
  vector3d jockey_pos;
  vector3d jockey_dir;
  rational_t jockey_speed;
  bool jockey;
  bool use_45_jockey;
  eJockeyAnim jockey_anim_a;
  eJockeyAnim jockey_anim_b;
  virtual void adjust_jockey_animation(const vector3d&, time_value_t);
  void conditional_compute_sector(region_node*, const vector3d&, const vector3d&);
  time_value_t repulsion_timer;
  vector3d repulsion_local_dest;
  bool process_repulsion(time_value_t);
  time_value_t repulsion_wait_timer;
  bool repulsion_wait;
public:
  ai_locomotion(ai_interface *own);
  virtual ~ai_locomotion();
  virtual bool frame_advance(time_value_t);
  virtual bool process_movement(time_value_t);
  virtual bool set_destination(const vector3d&, rational_t, bool, bool, bool);
  virtual bool set_facing(const vector3d&, rational_t);
  virtual bool set_facing_point(const vector3d&, rational_t);
  virtual bool set_num(const pstring&, rational_t);
  virtual bool get_num(const pstring&, rational_t&);
};

ai_locomotion::ai_locomotion(ai_interface *own)
{
  owner = own;

  current_path_graph = 0;
  current_path.clear();

  patrol_id = 0;
  xz_movement = false;

  start_pos = ZEROVEC;
  last_pos = ZEROVEC;
  target_pos = ZEROVEC;
  tgtrange = 1.0f;
  running_speed = false;

  patrol_radius = 0.5f;
  in_service = false;
  wait_until_reached = false;

  facing = false;
  playing_face_anim = false;
  face_dir = ZEROVEC;

  type = LOCOMOTION_NONE;

  turn_speed = 1.0f;

  repulsion_wait_timer = 0.0f;
  repulsion_wait = false;

  jockey_anim_a = _JOCKEY_ANIMS;
  jockey_anim_b = _JOCKEY_ANIMS;
  jockey_timer = -1.0f;
  jockey = false;
  jockey_speed = 2.0f;

  use_45_jockey = true;
  wait_for_facing = false;
}
